#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    const int N = 3;
    Student list[N];
    for (int i = 0; i < N; i++) {
        cout << "Student " << i + 1 << " (id name cgpa): ";
        cin >> list[i].id >> list[i].name >> list[i].cgpa;
    }
    cout << "\nID\tName\tCGPA" << endl;
    for (int i = 0; i < N; i++) {
        cout << list[i].id << "\t" << list[i].name << "\t" << list[i].cgpa << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    const int N = 4;
    Student list[N] = {
        {1, "Ali", 3.5},
        {2, "Sana", 3.9},
        {3, "Usman", 2.8},
        {4, "Hina", 3.1}
    };

    int target = 3;
    int found = -1;
    for (int i = 0; i < N; i++) {
        if (list[i].id == target) {
            found = i;
        }
    }
    if (found != -1) {
        cout << "Found: " << list[found].name << " (id " << target << ")" << endl;
    } else {
        cout << "Not found" << endl;
    }

    int best = 0;
    for (int i = 1; i < N; i++) {
        if (list[i].cgpa > list[best].cgpa) {
            best = i;
        }
    }
    cout << "Highest CGPA: " << list[best].name << " " << list[best].cgpa << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    const int N = 3;
    Student list[N] = {{1, "Ali", 3.5}, {2, "Sana", 3.9}, {3, "Usman", 2.8}};

    for (int i = 0; i < N - 1; i++) {
        for (int j = 0; j < N - 1 - i; j++) {
            if (list[j].cgpa < list[j + 1].cgpa) {
                Student t = list[j];
                list[j] = list[j + 1];
                list[j + 1] = t;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        cout << i + 1 << ". " << list[i].name << " " << list[i].cgpa << endl;
    }
    return 0;
}

